    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    fg = next(v for v in Counter(v for row in grid for v in row) if v != bg)

    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == fg]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    out = [row[:] for row in grid]

    # Fill gaps in the rectangular outline.
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if r in (r0, r1) or c in (c0, c1):
                if out[r][c] == bg:
                    out[r][c] = 2

    # Dense interrupted lines inside the outline are completed in color 2;
    # isolated interior foreground marks are recolored to 2.
    dense_rows = set()
    dense_cols = set()
    width, height = c1 - c0 + 1, r1 - r0 + 1
