        n = sum(grid[r][c] == fg for c in range(c0, c1 + 1))
        if n * 2 >= width:
            dense_rows.add(r)
    for c in range(c0 + 1, c1):
        n = sum(grid[r][c] == fg for r in range(r0, r1 + 1))
        if n * 2 >= height:
            dense_cols.add(c)

    for r in range(r0 + 1, r1):
        for c in range(c0 + 1, c1):
            if r in dense_rows or c in dense_cols:
                if out[r][c] == bg:
                    out[r][c] = 2
            elif out[r][c] == fg:
                out[r][c] = 2

    return out
